function renderDashboard(){const s=student(),hour=new Date().getHours(),greeting=hour<12?"Buenos días":hour<20?"Buenas tardes":"Buenas noches",average=(courses.reduce((sum,course)=>sum+course.grade,0)/courses.length).toFixed(1),attendance=Math.round(courses.reduce((sum,course)=>sum+course.attendance,0)/courses.length),academicState=courses.some(course=>course.state==="En alerta")?"Atención":s.status;$("#dashboard-name").textContent=`${greeting}, ${s.name.split(" ")[0]} 👋`;$("#dashboard-career").textContent=s.career;$("#dashboard-period").textContent=`${s.semester} · ${s.schedule}`;$("#dashboard-status").textContent=s.status;$("#dashboard-average").textContent=average;$("#dashboard-attendance").textContent=`${attendance}%`;$("#dashboard-courses").textContent=courses.length;$("#dashboard-academic-state").textContent=academicState}
