function renderToday(){const items=schedule.filter(item=>item.day===todayKey()),todayItems=calendarEntries().filter(item=>item.date===isoDate()&&item.status!=="completed"),currentTime=`${String(new Date().getHours()).padStart(2,"0")}:${String(new Date().getMinutes()).padStart(2,"0")}`,next=items.find(item=>item.time.split(" - ")[0]>=currentTime)||items[0];$("#today-date").textContent=`Hoy · ${formatToday()}`;$("#today-evaluations").innerHTML=todayItems.map(item=>{const meta=eventMeta(item.type),course=evaluationCourse(item);return`<article class="today-evaluation ${meta.tone}"><span>${meta.icon}</span><div><b>${item.type}: ${item.title}</b><p>${course?.name?`${course.name} · `:""}${item.time}${item.room?` · ${item.room}`:""}</p></div><button class="outline-btn" data-calendar-event="${item.key}">Ver detalle</button></article>`}).join("");$("#today-classes").innerHTML=items.length?items.map(item=>`<article class="today-class-card ${item===next?"next-class":""}"><div class="today-time">${item.time.split(" - ")[0]}<small>${item.time.split(" - ")[1]}</small></div><div><span class="today-subject-icon">📘</span><h4>${item.subject}</h4><p>${item.room} · ${item.professor}</p></div><button class="outline-btn" data-class="${item.subjectId}" data-class-day="${item.day}">Ver detalle</button></article>`).join(""):`<article class="today-empty"><span>◷</span><div><b>No tienes actividades académicas hoy.</b><p>Revisa tu calendario para conocer las próximas fechas importantes.</p></div></article>`}
function renderHomeMail(){const pending=mailData.filter(mail=>mail.unread).length,ordered=[...mailData].sort((a,b)=>Number(b.important&&b.unread)-Number(a.important&&a.unread)||Number(b.unread)-Number(a.unread)),preview=ordered.slice(0,3);$("#home-mail-count").textContent=`${pending} mensaje${pending===1?"":"s"} pendiente${pending===1?"":"s"}`;$("#home-mail-preview").innerHTML=preview.map(mail=>`<button class="home-mail-card ${mail.unread?"unread":"read"}" data-mail="${mailData.indexOf(mail)}"><span class="home-mail-icon">${mail.important?"★":"✉"}</span><div><small>${mail.from} · ${mail.date}</small><b>${mail.subject}</b><p>${mail.preview}</p></div>${mail.unread?"<em>No leído</em>":"<em>Leído</em>"}</button>`).join("")||"<div class='home-mail-empty'><span>📩</span><b>No tienes mensajes pendientes.</b><p>Tu bandeja está actualizada.</p></div>"}
function renderInternationalization(){const card=item=>`<article class="course-card international-card"><div class="card-top"><div><span class="eyebrow">${item.type.toUpperCase()}</span><h3>${item.name}</h3><p class="card-meta">${item.country} · ${item.university}</p></div><span class="badge ${item.status==="Postulación abierta"?"available":"request"}">${item.status}</span></div><p class="card-meta">Cierre: ${formatDate(item.deadline)}</p><div class="card-actions"><small>Convocatoria internacional</small><button class="outline-btn" data-international="${item.id}">Ver detalle</button></div></article>`;$("#international-programs").innerHTML=internationalPrograms.map(card).join("");$("#international-scholarships").innerHTML=internationalPrograms.slice(0,2).map(item=>`<article class="summary-row"><div><b>Beca movilidad internacional</b><p>${item.country} · Cierre ${formatDate(item.deadline)}</p></div><span class="badge available">Disponible</span></article>`).join("");$("#international-calls").innerHTML=internationalPrograms.map(item=>`<article class="summary-row"><div><b>${item.name}</b><p>${item.description}</p></div><button class="outline-btn" data-international="${item.id}">Ver detalle</button></article>`).join("")}
function internationalDetail(id){const item=internationalPrograms.find(program=>program.id===id);if(!item)return;const hasReminder=reminders().some(reminder=>reminder.internationalProgramId===id);$("#international-detail-content").innerHTML=`<div class="detail-title"><span class="eyebrow">🌎 INTERNACIONALIZACIÓN UBO</span><h2>${item.name}</h2><p>${item.type} · ${item.country}</p><span class="badge ${item.status==="Postulación abierta"?"available":"request"}">${item.status}</span></div><section class="class-info-card"><div><span>País</span><b>${item.country}</b></div><div><span>Universidad destino</span><b>${item.university}</b></div><div><span>Fecha límite</span><b>${formatDate(item.deadline)}</b></div></section><section class="card-section"><h3>Descripción</h3><article class="announcement-card"><p>${item.description}</p></article></section><section class="card-section"><h3>Requisitos</h3><article class="announcement-card"><p>${item.requirements.map(requirement=>`• ${requirement}`).join("<br>")}</p></article></section><div class="international-actions"><button class="primary-btn" data-international-reminder="${item.id}">${hasReminder?"Recordatorio agregado":"Agregar recordatorio"}</button><button class="outline-btn" data-toast="Documentos necesarios: certificado de alumno regular, notas y carta de motivación (demo).">Ver documentos necesarios</button></div>`;showScreen("international-detail")}
function addInternationalReminder(id){const item=internationalPrograms.find(program=>program.id===id),list=reminders();if(!item)return;if(!list.some(reminder=>reminder.internationalProgramId===id)){list.push({internationalProgramId:id,title:`Postulación internacional: ${item.name}`,date:item.deadline,time:"23:59",room:"Internacionalización UBO",type:"Evento UBO",subject:"Internacionalización UBO",when:"1 semana antes"});localStorage.setItem("uboReminders",JSON.stringify(list));toast("Recordatorio agregado al calendario académico.")}else toast("Este recordatorio ya está agregado.");internationalDetail(id)}
function savedOpportunities(){const list=json("uboSavedOpportunities",[]);return Array.isArray(list)?list:[]}
