function renderOpportunities(filter="Todas"){const filters=["Todas","Prácticas","Ayudantías","Empleo","Investigación"],visible=opportunities.filter(item=>filter==="Todas"||filter==="Prácticas"&&item.type.includes("Práctica")||filter==="Ayudantías"&&item.type.includes("Ayudantía")||filter==="Empleo"&&item.type==="Empleo"||filter==="Investigación"&&item.type==="Investigación");$("#opportunity-filters").innerHTML=filters.map(item=>`<button class="filter-btn ${filter===item?"active":""}" data-opportunity-filter="${item}">${item}</button>`).join("");$("#opportunities-list").innerHTML=visible.map(item=>`<article class="course-card international-card"><div class="card-top"><div><span class="eyebrow">${item.type.toUpperCase()}</span><h3>${item.title}</h3><p class="card-meta">${item.organization} · ${item.modality}</p></div><span class="badge ${item.status==="Disponible"?"available":"request"}">${item.status}</span></div><p class="card-meta">${item.career} · Cierre: ${formatDate(item.deadline)}</p><div class="card-actions"><small>${opportunitySaved(item.id)?"★ Guardada":"Convocatoria institucional"}</small><button class="outline-btn" data-opportunity="${item.id}">Ver detalle</button></div></article>`).join("")||"<p class='card-meta'>No hay oportunidades disponibles en este filtro.</p>";const saved=savedOpportunities().map(opportunity).filter(Boolean);$("#saved-opportunities").innerHTML=saved.map(item=>`<button class="summary-row" data-opportunity="${item.id}"><div><b>${item.title}</b><p>${item.organization} · Cierre ${formatDate(item.deadline)}</p></div><span class="badge available">Guardada</span></button>`).join("")||"<p class='card-meta'>Aún no guardas oportunidades.</p>"}
function opportunityDetail(id){const item=opportunity(id);if(!item)return;const hasReminder=reminders().some(reminder=>reminder.opportunityId===id);$("#opportunity-detail-content").innerHTML=`<div class="detail-title"><span class="eyebrow">💼 OPORTUNIDADES UBO</span><h2>${item.title}</h2><p>${item.organization} · ${item.type}</p><span class="badge ${item.status==="Disponible"?"available":"request"}">${item.status}</span></div><section class="class-info-card"><div><span>Modalidad</span><b>${item.modality}</b></div><div><span>Carrera</span><b>${item.career}</b></div><div><span>Fecha límite</span><b>${formatDate(item.deadline)}</b></div></section><section class="card-section"><h3>Descripción</h3><article class="announcement-card"><p>${item.description}</p></article></section><section class="card-section"><h3>Requisitos</h3><article class="announcement-card"><p>${item.requirements.map(requirement=>`• ${requirement}`).join("<br>")}</p></article></section><div class="international-actions"><button class="primary-btn" data-opportunity-save="${item.id}">${opportunitySaved(item.id)?"Oportunidad guardada":"Guardar oportunidad"}</button><button class="outline-btn" data-opportunity-reminder="${item.id}">${hasReminder?"Recordatorio agregado":"Agregar recordatorio"}</button><button class="outline-btn" data-toast="Documentos demo: CV actualizado, certificado de alumno regular y concentración de notas.">Ver documentos necesarios</button></div>`;showScreen("opportunity-detail")}
function saveOpportunity(id){const list=savedOpportunities();if(!list.includes(id)){list.push(id);store("uboSavedOpportunities",list);toast("Oportunidad guardada en tu perfil.")}else toast("Esta oportunidad ya está guardada.");opportunityDetail(id)}
function addOpportunityReminder(id){const item=opportunity(id),list=reminders();if(!item)return;if(!list.some(reminder=>reminder.opportunityId===id)){list.push({opportunityId:id,title:`Oportunidad UBO: ${item.title}`,date:item.deadline,time:"23:59",room:item.organization,type:"Evento UBO",subject:"Oportunidades UBO",when:"1 semana antes"});store("uboReminders",list);toast("Recordatorio agregado al calendario académico.")}else toast("Este recordatorio ya está agregado.");opportunityDetail(id)}
function opportunityCalendarEntries(){return opportunities.map(item=>({id:item.id,key:`opportunity:${item.id}`,source:"opportunity",type:"Evento UBO",title:`Oportunidad: ${item.title}`,date:item.deadline,time:"23:59",room:item.organization,subject:"Oportunidades UBO",description:item.description,opportunityId:item.id}))}
function marketplaceData(){const saved=json("uboMarketplacePosts",[]);return[...saved,...marketplacePosts]}
