function marketplacePost(id){return marketplaceData().find(item=>item.id===id)}
function renderMarketplace(filter="Todos"){const filters=["Todos","Libros","Tecnología","Apuntes","Intercambio","Gratis"],posts=marketplaceData().filter(item=>filter==="Todos"||filter===item.category||filter===item.type);$("#marketplace-filters").innerHTML=filters.map(item=>`<button class="filter-btn ${filter===item?"active":""}" data-marketplace-filter="${item}">${item}</button>`).join("");$("#marketplace-list").innerHTML=posts.map(item=>`<article class="community-card"><span class="eyebrow">${item.category} · ${item.type}</span><h3>${item.title}</h3><p>${item.description}</p><small>${item.user} · ${item.career} · ${item.date}</small><div class="card-actions"><span class="badge ${item.type==="Gratis"?"available":"request"}">${item.price}</span><button class="outline-btn" data-marketplace="${item.id}">Ver detalle</button></div></article>`).join("")||"<div class='home-mail-empty'><span>🛒</span><b>No hay publicaciones en este filtro.</b><p>Publica el primer recurso para la comunidad.</p></div>"}
function marketplaceDetail(id){const item=marketplacePost(id);if(!item)return;const isSaved=marketplaceSaved().includes(id);$("#marketplace-detail-content").innerHTML=`<div class="detail-title"><span class="eyebrow">🛒 MARKETPLACE UBO</span><h2>${item.title}</h2><p>${item.category} · ${item.type}</p><span class="badge ${item.type==="Gratis"?"available":"request"}">${item.status}</span></div><section class="class-info-card"><div><span>Publicado por</span><b>${item.user}</b></div><div><span>Carrera</span><b>${item.career}</b></div><div><span>Precio</span><b>${item.price}</b></div></section><section class="card-section"><h3>Descripción</h3><article class="announcement-card"><p>${item.description}</p></article></section><div class="international-actions"><button class="primary-btn" data-marketplace-save="${id}">${isSaved?"Publicación guardada":"Guardar"}</button><button class="outline-btn" data-toast="Contacto demo: puedes coordinar con ${item.user} mediante Comunidad UBO.">Contactar usuario</button><button class="outline-btn" data-toast="Publicación compartida en modo demo.">Compartir</button></div>`;showScreen("marketplace-detail")}
function saveMarketplacePost(id){const list=marketplaceSaved();if(!list.includes(id)){list.push(id);store("uboSavedMarketplacePosts",list);toast("Publicación guardada.")}else toast("Esta publicación ya está guardada.");marketplaceDetail(id)}
function createMarketplacePost(form){const title=$("#marketplace-title").value.trim(),description=$("#marketplace-description").value.trim(),type=$("#marketplace-type").value,price=$("#marketplace-price").value.trim();if(!title||!description)return;const s=student(),posts=json("uboMarketplacePosts",[]);posts.unshift({id:`market-${Date.now()}`,user:s.name,career:s.career,title,description,category:$("#marketplace-category").value,type,price:type==="Gratis"?"Gratis":price||"A convenir",date:"Ahora",status:"Disponible"});store("uboMarketplacePosts",posts);form.reset();showScreen("marketplace");toast("Publicación creada en modo demo.")}
function studentGoals(){const list=json("uboStudentGoals",[]);return Array.isArray(list)?list:[]}
function trajectoryStats(){const average=(courses.reduce((sum,item)=>sum+item.grade,0)/courses.length).toFixed(1),attendance=Math.round(courses.reduce((sum,item)=>sum+item.attendance,0)/courses.length),approved=2,current=courses.filter(item=>item.state==="En curso").length,failed=1,pending=12,completed=approved+current,percentage=Math.round(completed/(completed+pending+failed)*100);return{average,attendance,approved,current,failed,pending,percentage}}
function renderTrajectory(){const s=student(),stats=trajectoryStats(),goals=studentGoals();$("#trajectory-summary").innerHTML=`<article class="student-id"><div class="student-id-head"><div><b>${escapeHTML(s.name)}</b><p>${escapeHTML(s.career)} · ${escapeHTML(s.semester)}</p></div><div class="student-id-avatar">${initials(s.name)}</div></div><div class="summary-row"><div><b>Promedio ${stats.average}</b><p>Asistencia ${stats.attendance}% · Avance ${stats.percentage}%</p></div><span class="badge available">En progreso</span></div></article>`;$("#trajectory-progress").innerHTML=`<article class="info-card"><div class="card-top"><div><b>Avance curricular</b><p>${stats.approved} aprobados · ${stats.current} actuales · ${stats.pending} pendientes · ${stats.failed} reprobado</p></div><b>${stats.percentage}%</b></div><div class="trajectory-bar"><span style="width:${stats.percentage}%"></span></div></article>`;$("#trajectory-history").innerHTML=courses.map(item=>`<article class="summary-row"><div><b>${item.name}</b><p>${s.semester} · Nota ${item.grade}</p></div><span class="badge ${item.state==="En alerta"?"late":"available"}">${item.state}</span></article>`).join("");$("#trajectory-achievements").innerHTML=studentAchievements.map(item=>`<article class="announcement-card"><b>${item.icon} ${item.title}</b><p>${item.description}</p></article>`).join("");$("#trajectory-goals").innerHTML=goals.map(goal=>`<article class="summary-row"><div><b>${escapeHTML(goal.title)}</b><p>${goal.done?"Objetivo completado":"En progreso"}</p></div><button class="outline-btn" data-goal-toggle="${goal.id}">${goal.done?"Completado":"Marcar listo"}</button></article>`).join("")||"<p class='card-meta'>Aún no tienes objetivos. Crea uno para comenzar.</p>"}
function createStudentGoal(form){const title=$("#trajectory-goal-input").value.trim();if(!title)return;const goals=studentGoals();goals.unshift({id:`goal-${Date.now()}`,title,done:false});store("uboStudentGoals",goals);form.reset();renderTrajectory();toast("Objetivo agregado.")}
function toggleStudentGoal(id){const goals=studentGoals().map(goal=>goal.id===id?{...goal,done:!goal.done}:goal);store("uboStudentGoals",goals);renderTrajectory();toast("Objetivo actualizado.")}
function communityData(){const saved=json("uboCommunityPosts",[]);return[...saved,...communityPosts]}
function renderCommunity(filter="Todas"){const filters=["Todas","Apuntes","Académico","Vida universitaria","Campus","Oportunidades"],posts=communityData().filter(post=>filter==="Todas"||post.category===filter);$("#community-filters").innerHTML=filters.map(item=>`<button class="filter-btn ${item===filter?"active":""}" data-community-filter="${item}">${item}</button>`).join("");$("#community-list").innerHTML=posts.map(post=>`<article class="community-card"><span class="eyebrow">${post.category}</span><h3>${post.title}</h3><p>${post.content}</p><small>${post.user} · ${post.career} · ${post.date}</small><div class="card-actions"><span>♥ ${post.likes} · 💬 ${post.comments.length}</span><button class="outline-btn" data-community="${post.id}">Ver publicación</button></div></article>`).join("")||"<div class='home-mail-empty'><span>🤝</span><b>Todavía no hay publicaciones.</b><p>Sé el primero en compartir.</p></div>"}
function communityDetail(id){const post=communityData().find(item=>item.id===id);if(!post)return;$("#community-detail-content").innerHTML=`<div class="detail-title"><span class="eyebrow">${post.category.toUpperCase()}</span><h2>${post.title}</h2><p>${post.user} · ${post.career} · ${post.date}</p></div><article class="announcement-card"><p>${post.content}</p></article><div class="community-actions"><button class="outline-btn" data-community-like="${id}">♥ ${post.likes} Me gusta</button></div><section class="card-section"><h3>Comentarios</h3><div class="stack">${post.comments.map(comment=>`<article class="summary-row"><div><b>Estudiante UBO</b><p>${comment}</p></div></article>`).join("")||"<p class='card-meta'>Aún no hay comentarios.</p>"}</div><form id="community-comment-form" class="form-card"><label>Agregar comentario<textarea id="community-comment" required></textarea></label><button class="primary-btn" type="submit" data-community-comment-id="${id}">Comentar</button></form></section>`;showScreen("community-detail")}
function updateCommunity(id,change){const saved=json("uboCommunityPosts",[]),post=saved.find(item=>item.id===id)||communityPosts.find(item=>item.id===id);if(!post)return;const next={...post,...change,comments:change.comments||post.comments};if(!saved.some(item=>item.id===id)){saved.unshift(next)}else Object.assign(saved.find(item=>item.id===id),next);localStorage.setItem("uboCommunityPosts",JSON.stringify(saved));communityDetail(id)}
// Prototipo preparado para evolucionar a IA institucional con backend, RAG y fuentes oficiales.
const aiKnowledgeBase={courses,schedule,evaluations,assignments,events,documents,internationalPrograms,communityPosts,mailData,opportunities,marketplacePosts};
function aiAnswer(question){const q=question.toLowerCase(),items=list=>list.map(item=>`• ${item}`).join("<br>");if(q.includes("hoy")){const classes=schedule.filter(item=>item.day===todayKey());return classes.length?`Hoy tienes:<br>${items(classes.map(item=>`${item.subject} · ${item.time} · ${item.room}`))}`:"No tienes clases programadas hoy."}if(q.includes("evaluaci")||q.includes("prueba"))return `Tus evaluaciones próximas:<br>${items(evaluations.filter(item=>item.status!=="completed").map(item=>`${item.title} · ${formatDate(item.date)} · ${item.time}`))}`;if(q.includes("entrega"))return `Tus entregas pendientes:<br>${items(assignments.filter(item=>item.status!=="completed").map(item=>`${item.title} · ${formatDate(item.dueDate)} · ${item.dueTime}`))}`;if(q.includes("asistencia")||q.includes("faltar")){const average=Math.round(courses.reduce((sum,item)=>sum+item.attendance,0)/courses.length),risk=courses.filter(item=>item.attendance<80);return `Tu asistencia promedio es ${average}%.${risk.length?` Revisa especialmente ${risk.map(item=>item.name).join(", ")}.`:" Cumples una situación académica favorable."}`}if(q.includes("document")||q.includes("certificado"))return "Puedes solicitar certificados desde Perfil → Documentos. Allí verás documentos disponibles, en revisión y generados.";if(q.includes("internacional"))return `Oportunidades internacionales:<br>${items(internationalPrograms.map(item=>`${item.name} · cierre ${formatDate(item.deadline)}`))}`;if(q.includes("comunidad"))return `En Comunidad UBO encontrarás:<br>${items(communityData().slice(0,3).map(item=>`${item.category}: ${item.title}`))}`;if(q.includes("correo")||q.includes("mensaje")){const unread=mailData.filter(item=>item.unread);return unread.length?`Tienes ${unread.length} mensaje${unread.length===1?"":"s"} pendiente${unread.length===1?"":"s"}:<br>${items(unread.slice(0,3).map(item=>`${item.sender} · ${item.subject}`))}`:"Tu correo institucional está al día."}return "No encuentro esa información todavía. Puedes revisar Centro de ayuda UBO."}
function renderAiAssistant(messages=[]){const initial=messages.length?messages:[{role:"assistant",text:"Hola, soy el Asistente IA UBO demo. ¿En qué puedo orientarte?"}];$("#ai-chat").innerHTML=initial.map(message=>`<article class="ai-message ${message.role}"><b>${message.role==="user"?"Tú":"Asistente UBO"}</b><p>${message.text}</p></article>`).join("");$("#ai-chat").dataset.messages=JSON.stringify(initial)}
// Widget global preparado para backend institucional, autenticación real, RAG, modelos IA y fuentes oficiales UBO.
function renderAiWidget(messages=[]){const initial=messages.length?messages:[{role:"assistant",text:"Hola, soy tu Asistente IA UBO. ¿En qué puedo ayudarte?"}],node=$("#ai-widget-messages");if(!node)return;node.innerHTML=initial.map(message=>`<article class="ai-message ${message.role}"><b>${message.role==="user"?"Tú":"Asistente UBO"}</b><p>${message.text}</p></article>`).join("");node.dataset.messages=JSON.stringify(initial);node.scrollTop=node.scrollHeight}
function askAiWidget(question){const node=$("#ai-widget-messages");if(!node)return;let messages=[];try{messages=JSON.parse(node.dataset.messages||"[]")}catch{}messages.push({role:"user",text:escapeHTML(question)},{role:"assistant",text:aiAnswer(question)});renderAiWidget(messages)}
