function renderAttendance(){$("#attendance-list").innerHTML=courses.map(c=>`<article class="course-card"><h3>${c.name}</h3><p class="card-meta">${c.attendance}% de asistencia registrada</p><div class="card-actions"><span class="badge ${c.attendance<75?"late":c.attendance<80?"request":"available"}">${c.attendance<75?"Riesgo académico":c.attendance<80?"En seguimiento":"Cumple requisito"}</span><button class="outline-btn" data-go="attendance-calculator" data-attendance-course="${c.id}">Calcular</button></div></article>`).join("");$("#attendance-course").innerHTML=courses.map(c=>`<option value="${c.id}">${c.name}</option>`).join("");setAttendanceCalculatorValues($("#attendance-course").value)}
function calculateAttendance(){const total=Number($("#attendance-total").value),minimum=Number($("#attendance-minimum").value),held=Number($("#classes-held").value),attended=Number($("#classes-attended").value),future=Number($("#future-classes").value),result=$("#attendance-result"),valid=[total,minimum,held,attended,future].every(Number.isFinite)&&total>0&&minimum>0&&minimum<=100&&held>=0&&held<=total&&attended>=0&&attended<=held&&future>=0&&future<=total-held;if(!valid){result.textContent="Verifica el total, las clases realizadas, asistidas y la proyección futura.";result.className="attendance-result result late";result.classList.remove("hidden");return}const missed=held-attended,needed=Math.ceil(total*minimum/100),allowed=total-needed,current=held?attended/held*100:0,projectedAttended=attended+future,projected=projectedAttended/total*100,maxPossible=attended+(total-held),status=maxPossible<needed?{label:"Reprobado por asistencia",tone:"late",detail:"Aunque asistas a todas las clases restantes, ya no alcanzas el mínimo."}:projected>=minimum?{label:"Cumple requisito",tone:"available",detail:"La proyección cumple el mínimo requerido para el ramo."}:{label:"Riesgo académico",tone:"request",detail:"Aún puedes cumplir si aumentas tus asistencias futuras."};result.className=`attendance-result result ${status.tone}`;result.innerHTML=`<div class="attendance-result-status"><span class="badge ${status.tone}">${status.label}</span><strong>${projected.toFixed(1)}%</strong><small>Proyección final</small></div><div class="attendance-result-grid"><span><b>${current.toFixed(1)}%</b>Porcentaje actual</span><span><b>${attended}</b>Clases asistidas</span><span><b>${missed}</b>Inasistencias actuales</span><span><b>${needed}</b>Clases necesarias</span><span><b>${allowed}</b>Inasistencias permitidas</span><span><b>${projectedAttended}/${total}</b>Asistencias proyectadas</span></div><p>${status.detail}</p>`;result.classList.remove("hidden")}
