function renderAlerts(){const list=buildNotifications(),priorityLabel=item=>item.priority==="high"?"Alta prioridad":item.priority==="medium"?"Próxima":"Informativa",card=(item,compact=false)=>{const meta=notificationMeta(item.type),course=courses.find(entry=>entry.id===item.subjectId),isRead=item.read;return`<article class="alert-card ${item.priority} ${isRead?"is-read":""}"><div class="alert-card-top"><span class="alert-icon">${meta.icon}</span><div><span class="eyebrow">${meta.label} · ${priorityLabel(item)}</span><h3>${item.title}</h3></div><span class="badge ${isRead?"available":item.priority==="high"?"late":item.priority==="medium"?"request":"available"}">${isRead?"Leída":priorityLabel(item)}</span></div><p class="alert-description">${item.message}</p>${course?`<p class="alert-subject">📚 ${course.name}</p>`:""}<div class="alert-meta"><span>📅 ${formatDate(item.date)}</span>${isRead?"<span>✓ Completada</span>":"<span>Sin leer</span>"}</div>${compact?"":`<div class="alert-actions"><button class="outline-btn" data-notification="${item.id}">Ver aviso</button>${isRead?"":`<button class="text-btn" data-notification-read="${item.id}">Marcar leída</button>`}</div>`}</article>`},active=list.filter(item=>!item.read),history=list.filter(item=>item.read);$("#alerts-list").innerHTML=active.map(item=>card(item)).join("")||"<p class='card-meta'>No tienes alertas activas. Tu situación académica está al día.</p>";$("#alerts-history").innerHTML=history.map(item=>card(item)).join("")||"<p class='card-meta'>Aún no hay alertas en tu historial.</p>";$("#home-alerts").innerHTML=active.filter(item=>item.priority!=="low").slice(0,3).map(item=>card(item,true)).join("")||"<p class='card-meta'>No tienes alertas importantes.</p>"}
