function addCampusLocationReminder(id){const location=campusLocations.find(item=>item.id===id),list=reminders();if(!location)return;const exists=list.some(item=>item.campusLocationId===id);if(!exists){list.push({campusLocationId:id,title:`Visitar ${location.name}`,date:isoDate(),time:"Durante el día",room:`${location.building} · ${location.floor}`,type:"Campus UBO",when:"El mismo día",subject:"Campus UBO"});localStorage.setItem("uboReminders",JSON.stringify(list));toast("Recordatorio de ubicación agregado.")}else toast("Este recordatorio ya está agregado.");if(currentScreen==="campus-location-detail")campusLocationDetail(id)}
function renderHelpCenter(search=helpSearch){helpSearch=search;$("#help-search").value=search;const query=search.trim().toLowerCase(),items=helpArticles.filter(article=>!query||[article.category,article.title,article.summary,article.content,...article.keywords].join(" ").toLowerCase().includes(query)),categories=helpArticles.filter((article,index,list)=>list.findIndex(entry=>entry.category===article.category)===index);$("#help-categories").innerHTML=categories.map(article=>`<article class="help-category-card"><span>${article.icon}</span><div><h3>${article.category}</h3><p>${article.summary}</p></div><button class="outline-btn" data-help="${article.id}">Ver ayuda</button></article>`).join("");$("#help-faq-list").innerHTML=items.map(article=>`<button class="help-faq-row" data-help="${article.id}"><span>${article.icon}</span><div><b>${article.title}</b><p>${article.summary}</p></div><i>›</i></button>`).join("")||"<p class='card-meta'>No encontramos ayuda para esa búsqueda.</p>"}
