function renderVirtual(){$("#virtual-list").innerHTML=courses.map(c=>`<article class="virtual-card"><div class="card-top"><div><h3>${c.name}</h3><p>${c.teacher}</p></div><span class="badge available">Activa</span></div><p>Actualización: ${c.updated}</p><div class="card-actions"><small>${c.materials} materiales · ${c.pending} trabajos pendientes</small><button class="outline-btn" data-virtual="${c.id}">Ver aula</button></div></article>`).join("")}
function virtualDetail(id){const c=courses.find(x=>x.id===id);if(!c)return;const materials=["Clase 01 - Introducción","Presentación unidad 1","Guía de ejercicios","Video complementario"],tasks=assignments.filter(item=>item.subjectId===c.id&&item.status!=="completed");$("#virtual-detail-content").innerHTML=`<div class="detail-title"><h2>${c.name}</h2><p>${c.teacher}</p></div><section class="card-section"><h3>Material del profesor</h3>${materials.map(m=>`<div class="material-row"><span class="icon-badge blue">▤</span><div><b>${m}</b><p>Recurso publicado por el profesor.</p></div><button class="small-action" data-toast="Material disponible en modo demo.">Abrir</button></div>`).join("")}</section><section class="card-section"><h3>Trabajos pendientes</h3>${tasks.map(item=>{const state=assignmentStatus(item);return`<div class="task-row"><span class="badge ${state.priorityTone}">${state.priority}</span><div><b>${item.title}</b><p>${state.due} · ${item.dueTime}</p></div></div>`}).join("")||"<p class='card-meta'>No tienes trabajos pendientes.</p>"}</section>`;showScreen("virtual-detail")}
function renderSummary(){const avg=(courses.reduce((sum,c)=>sum+c.grade,0)/courses.length).toFixed(1);$("#summary .summary-card strong").textContent=avg;$("#summary-list").innerHTML=`<section class="history-card"><h3>Historial por semestre</h3><div class="semester-history"><div><b>2025-2</b><span>Promedio 5.5</span><small>2 aprobados · 0 reprobados</small></div><div><b>2026-1</b><span>Promedio ${avg}</span><small>6 ramos en curso</small></div></div></section><div class="summary-row"><div><b>Ramos aprobados</b><p>Programación I · Matemática I</p></div><span class="badge available">2</span></div><div class="summary-row"><div><b>Ramos pendientes</b><p>${courses.filter(c=>c.state==="En curso").map(c=>c.name).join(" · ")}</p></div><span class="badge request">5</span></div><div class="summary-row"><div><b>Ramos que debes volver a cursar</b><p>Álgebra · pendiente de confirmación académica.</p></div><span class="badge late">1</span></div>`}
function renderProfile(){const s=student(),p=$("#profile"),avatar=initials(s.name);p.querySelector(".avatar-large").textContent=avatar;p.querySelector(".profile-hero h2").textContent=s.name;p.querySelector(".profile-hero p").textContent=s.career;p.querySelector(".profile-hero .status").textContent=s.status;const lines=p.querySelectorAll(".info-card p span");lines[0].textContent=s.university;lines[1].textContent=`${s.semester} · ${s.schedule}`;lines[2].textContent=s.email;$(".avatar-small").textContent=avatar;const dashboardAvatar=$("#home .dashboard-avatar-btn");if(dashboardAvatar)dashboardAvatar.textContent=avatar;const dashboardName=$("#dashboard-name");if(dashboardName)dashboardName.textContent=`Hola, ${s.name.split(" ")[0]} 👋`}
function renderPersonal(){const s=student(),option=(items,value)=>items.map(x=>`<option ${x===value?"selected":""}>${x}</option>`).join(""),careers=["Administración Pública","Contador Auditor","Derecho","Enfermería","Ingeniería Civil Industrial","Ingeniería Comercial","Ingeniería Informática","Kinesiología","Medicina Veterinaria","Pedagogía en Educación Física","Psicología"];$("#personal-data").innerHTML=`<div class="section-intro"><h2>Datos personales</h2><p>Información registrada en UBO.</p></div><form id="personal-form" class="form-card personal-form"><label>Nombre completo<input name="name" value="${escapeHTML(s.name)}" disabled required></label><label>RUT<input name="rut" value="${escapeHTML(s.rut)}" disabled required></label><label>Carrera<select name="career" disabled>${option(careers,s.career)}</select></label><label>Semestre<select name="semester" disabled>${option(["2026-1","2026-2","2027-1","2027-2"],s.semester)}</select></label><label>Jornada<select name="schedule" disabled>${option(["Vespertina","Diurna"],s.schedule)}</select></label><label>Correo institucional<input name="email" type="email" value="${escapeHTML(s.email)}" disabled required></label><label>Estado<select name="status" disabled>${option(["Estudiante regular","Pendiente","Egresado","Suspendido"],s.status)}</select></label><label>Universidad<input value="${escapeHTML(s.university)}" disabled></label><p id="personal-error" class="login-error"></p><button id="edit-personal" class="primary-btn" type="button">Editar datos</button><div id="personal-edit-actions" class="hidden"><button class="primary-btn" type="submit">Guardar cambios</button><button id="cancel-personal" class="text-login-btn" type="button">Cancelar</button></div></form>`}
function savePersonal(form){const v=Object.fromEntries(new FormData(form).entries()),error=$("#personal-error"),validName=/^[A-Za-zÁÉÍÓÚáéíóúÑñÜü\s]+$/.test(v.name.trim()),validRut=/^\d{1,2}(?:\.\d{3}){1,2}-[\dKk]$|^\d{7,8}-[\dKk]$/.test(v.rut.trim()),validMail=v.email.trim().toLowerCase().endsWith("@pregrado.ubo.cl");if(!validName||!validRut||!validMail){error.textContent=!validName?"El nombre solo puede contener letras y espacios.":!validRut?"Ingresa un RUT válido. Ejemplo: 12.345.678-9":"Debes usar un correo institucional @pregrado.ubo.cl";error.classList.add("show");toast(error.textContent);return}saveStudent({...student(),...Object.fromEntries(Object.entries(v).map(([k,value])=>[k,value.trim()]))});renderProfile();renderPersonal();toast("Datos actualizados correctamente.")}
function renderStudentCard(){const s=student();$("#student-card-content").innerHTML=`<article class="student-id"><div class="student-id-head"><div><b>UNIVERSIDAD BERNARDO O'HIGGINS</b><p>Credencial estudiantil digital</p></div><div class="student-id-avatar">${initials(s.name)}</div></div><h3>${escapeHTML(s.name)}</h3><p>${escapeHTML(s.career)}</p><p>RUT: ${escapeHTML(s.rut)} · ${escapeHTML(s.schedule)}</p><p>${escapeHTML(s.email)}</p><div class="student-id-foot"><span>${escapeHTML(s.status)}<br><small>Código UBO-2026-1048</small></span><span class="demo-qr" aria-label="Código QR simulado" role="img"></span></div></article>`}
function renderBenefits(){const benefits=[["▤","Biblioteca","Préstamo de libros, espacios y recursos digitales.","Disponible","Ver detalle"],["+","Convenios de salud","Atención y convenios preferentes.","Disponible","Ver detalle"],["★","Actividades deportivas","Talleres y selecciones UBO.","Disponible","Más información"],["♡","Apoyo psicológico","Acompañamiento confidencial para estudiantes.","Requiere solicitud","Solicitar"],["?","Orientación académica","Apoyo para tu trayectoria académica.","Disponible","Ver detalle"],["$","Becas","Información y orientación para postulaciones.","Requiere solicitud","Solicitar"],["♫","Convenios culturales","Panorama cultural y actividades UBO.","Disponible","Ver detalle"],["%","Descuentos estudiantiles","Beneficios de comercios y servicios adheridos.","Disponible","Ver detalle"]];$("#benefits-list").innerHTML=benefits.map(b=>`<article class="benefit-card"><span class="icon-badge blue">${b[0]}</span><div><b>${b[1]}</b><p>${b[2]}</p><span class="badge ${b[3]==="Disponible"?"available":"request"}">${b[3]}</span></div><button class="outline-btn" data-benefit="${b[4]}">${b[4]}</button></article>`).join("")}
function renderMail(){const search=$("#mail-search").value.trim().toLowerCase(),visible=mailData.filter(m=>(mailFilter==="Todos"||mailFilter==="No leídos"&&m.unread||mailFilter==="Importantes"&&m.important||mailFilter==="Universidad"&&m.tag==="Universidad")&&`${m.from} ${m.subject}`.toLowerCase().includes(search));$("#mail-address").textContent=student().email;$("#mail-filters").innerHTML=["Todos","No leídos","Importantes","Universidad"].map(f=>`<button class="filter-btn ${f===mailFilter?"active":""}" data-mail-filter="${f}">${f}</button>`).join("");$("#mail-list").innerHTML=visible.map(m=>`<button class="mail-card ${m.unread?"unread":""}" data-mail="${mailData.indexOf(m)}"><div class="mail-meta"><b>${m.from}</b><span>${m.date}</span></div><b>${m.important?"★ ":""}${m.subject}</b><p>${m.preview}</p><span class="badge request">${m.tag}</span></button>`).join("")||"<p class='card-meta'>No hay correos en este filtro.</p>"}
function renderMailDetail(){const m=mailData[selectedMail];m.unread=false;renderHomeMail();$("#mail-detail-content").innerHTML=`<div class="detail-title"><h2>${m.subject}</h2><p>${m.from} · ${m.date}</p><span class="badge request">${m.tag}</span></div><article class="info-card"><p>${m.body}</p></article><div class="mail-detail-actions"><button class="primary-btn" data-go="institutional-mail">Volver al correo</button><button class="outline-btn" data-mail-toggle="important">${m.important?"Quitar importante":"Marcar importante"}</button><button class="outline-btn" data-mail-toggle="unread">Marcar como no leído</button></div>`}
function reminders(){const list=json("uboReminders",[]);return Array.isArray(list)?list:[]}
function renderCalendarEvents(items){const order=["Evaluación","Entrega","Evento UBO","Biblioteca","Feriado","Recordatorio"],labels={"Evaluación":"Evaluaciones",Entrega:"Entregas","Evento UBO":"Eventos UBO",Biblioteca:"Biblioteca",Feriado:"Feriados",Recordatorio:"Recordatorios"},groups=order.map(type=>[type,items.filter(item=>item.type===type)]).filter(([,group])=>group.length);return groups.length?groups.map(([type,group])=>{const meta=eventMeta(type);return`<section class="calendar-category ${meta.tone}"><div class="calendar-category-title"><span>${meta.icon}</span><h3>${labels[type]}</h3><small>${group.length}</small></div>${group.map(item=>`<button class="calendar-event-card" data-calendar-event="${item.key}"><div><b>${item.title}</b><p>${formatDate(item.date)} · ${item.time}${item.subject?` · ${item.subject}`:""}</p></div><i>›</i></button>`).join("")}</section>`}).join(""):"<p class='card-meta'>No hay eventos para este día.</p>"}
function renderCalendar(selectedDay=null){const monthDate=new Date(2026,8,1),year=monthDate.getFullYear(),month=monthDate.getMonth(),prefix=`${year}-${String(month+1).padStart(2,"0")}-`,entries=calendarEntries().filter(item=>item.date?.startsWith(prefix)),week=["L","M","X","J","V","S","D"].map(d=>`<span class="calendar-weekday">${d}</span>`),blank=Array.from({length:(monthDate.getDay()+6)%7},()=>"<span class='calendar-empty'></span>"),days=Array.from({length:new Date(year,month+1,0).getDate()},(_,i)=>{const d=i+1,items=entries.filter(item=>Number(item.date.slice(-2))===d),meta=items[0]&&eventMeta(items[0].type);return`<button class="calendar-day ${items.length?`event ${meta.tone}`:""} ${selectedDay===d?"selected":""}" data-day="${d}">${d}</button>`});$("#calendar-month-label").textContent=`${new Intl.DateTimeFormat("es-CL",{month:"long",year:"numeric"}).format(monthDate)} · Fechas y recordatorios.`;$("#calendar-grid").innerHTML=[...week,...blank,...days].join("");$("#calendar-detail").innerHTML=renderCalendarEvents(selectedDay?entries.filter(item=>Number(item.date.slice(-2))===selectedDay):entries)}
function calendarEventDetail(key){const item=calendarEntries().find(entry=>entry.key===key),course=evaluationCourse(item||{});if(!item)return;const meta=eventMeta(item.type),hasReminder=item.source==="reminder"||reminders().some(reminder=>reminder.evaluationId===item.id||reminder.assignmentId===item.id);$("#calendar-event-detail-content").innerHTML=`<div class="detail-title"><span class="eyebrow">${meta.icon} ${item.type.toUpperCase()}</span><h2>${item.title}</h2><p>${course?.name||item.subject||"Actividad institucional"}</p><span class="badge ${meta.tone}">${relativeEvent(item)}</span></div><section class="class-info-card"><div><span>Tipo</span><b>${item.type}${item.eventType?` · ${item.eventType}`:""}</b></div><div><span>Fecha</span><b>${formatDate(item.date)}</b></div><div><span>Hora</span><b>${item.time||"Por confirmar"}</b></div><div><span>Sala</span><b>${item.room||"Por confirmar"}</b></div><div><span>Recordatorio</span><b class="${hasReminder?"success-text":""}">${hasReminder?"Configurado":"Sin configurar"}</b></div></section><section class="card-section"><h3>Descripción</h3><article class="announcement-card"><p>${item.description||"Sin descripción adicional."}</p></article></section>${course?`<div class="event-detail-actions"><button class="primary-btn" data-calendar-course="${course.id}">Ver ramo</button><button class="outline-btn" data-calendar-virtual="${course.id}">Ver aula virtual</button></div>`:""}`;showScreen("calendar-event-detail")}
function renderDae(){const s=student(),history=json("uboDaeRequests",[]);$("#dae-name").value=s.name;$("#dae-email").value=s.email;$("#dae-history").innerHTML=history.map(x=>`<article class="summary-row"><div><b>${escapeHTML(x.subject)}</b><p>${escapeHTML(x.type)} · ${escapeHTML(x.date)}</p></div><span class="badge request">Enviada</span></article>`).join("")||"<p class='card-meta'>Aún no envías solicitudes.</p>"}
function submitDae(form){const subject=$("#dae-subject").value.trim(),message=$("#dae-message").value.trim();if(!subject||!message){toast("Completa asunto y mensaje.");return}const history=json("uboDaeRequests",[]);history.unshift({subject,type:$("#dae-type").value,date:new Date().toLocaleDateString("es-CL")});localStorage.setItem("uboDaeRequests",JSON.stringify(history));form.reset();renderDae();toast("Solicitud enviada a DAE en modo demo.")}
function saveReminder(form){const title=$("#reminder-title").value.trim(),date=$("#reminder-date").value;if(!title||!date){toast("Completa título y fecha del recordatorio.");return}const list=reminders();list.push({title,date,type:$("#reminder-type").value,when:$("#reminder-when").value});localStorage.setItem("uboReminders",JSON.stringify(list));form.reset();renderCalendar(Number(date.slice(-2)));toast("Recordatorio guardado correctamente.")}
function renderScreen(id){({home:()=>{renderProfile();renderDashboard();renderToday();renderHomeAttention();renderHomeNotifications();renderHomeMail();renderHomeEvents();renderHomeDeliveries();renderEvaluations();renderDocuments();renderCampusEvents();renderLibrary();renderCampusMap();renderHelpCenter()},"weekly-schedule":renderWeeklySchedule,evaluations:renderEvaluations,courses:renderCourses,attendance:renderAttendance,assignments:()=>renderAssignments(),notifications:()=>renderNotifications(),documents:renderDocuments,"campus-events":renderCampusEvents,internationalization:renderInternationalization,community:()=>renderCommunity(),"ai-assistant":()=>renderAiAssistant(),library:()=>renderLibrary(),"campus-map":()=>renderCampusMap(),"help-center":()=>renderHelpCenter(),alerts:renderAlerts,certificates:renderCertificates,virtual:renderVirtual,summary:renderSummary,profile:renderProfile,"personal-data":renderPersonal,"student-card":renderStudentCard,"student-benefits":renderBenefits,"institutional-mail":renderMail,"mail-detail":renderMailDetail,"dae-contact":renderDae,"academic-calendar":renderCalendar}[id])?.()}
function prepareLogin(){const remember=$("#remember-username"),legacy=localStorage.getItem("uboRememberedUsername"),remembered=localStorage.getItem("uboRememberedUser")||legacy||"";if(!localStorage.getItem("uboRememberedUser")&&legacy)localStorage.setItem("uboRememberedUser",legacy);localStorage.removeItem("uboRememberedUsername");localStorage.removeItem("uboRememberUsername");$("#loginUsername").value=remembered;$("#loginPassword").value="";$("#loginPassword").type="password";remember.checked=Boolean(remembered);$("#login-error").classList.remove("show")}
const baseCalendarEntries=calendarEntries,baseBuildNotifications=buildNotifications,baseRenderScreen=renderScreen,baseTitle=title;
title=id=>id==="opportunities"?"Oportunidades UBO":id==="opportunity-detail"?"Detalle de oportunidad":id==="marketplace"?"Marketplace UBO":id==="marketplace-detail"?"Detalle de publicación":id==="marketplace-create"?"Nueva publicación":id==="student-trajectory"?"Mi Trayectoria":baseTitle(id);
calendarEntries=()=>[...baseCalendarEntries(),...opportunityCalendarEntries()].sort((a,b)=>a.date.localeCompare(b.date)||String(a.time).localeCompare(String(b.time)));
buildNotifications=()=>{const list=baseBuildNotifications(),state=notificationState();opportunities.filter(item=>daysUntil(item.deadline)>=0&&daysUntil(item.deadline)<=7).forEach(item=>list.push({id:`opportunity:${item.id}`,type:"event",title:"Oportunidad UBO próxima",message:`${item.title} · ${item.organization} · cierre ${formatDate(item.deadline)}`,date:item.deadline,priority:daysUntil(item.deadline)<=2?"high":"medium",opportunityId:item.id,read:Boolean(state[`opportunity:${item.id}`]?.read)}));list.sort((a,b)=>a.date.localeCompare(b.date));notifications.splice(0,notifications.length,...list);return notifications};
function ensureOpportunityProfileAccess(){const settings=$("#profile .settings-list"),saved=savedOpportunities().length;if(settings&&!$("#profile-opportunities-access"))settings.insertAdjacentHTML("beforebegin",`<section id="profile-opportunities-access" class="card-section"><button class="quick-action-card" data-go="opportunities"><span class="quick-action-icon">💼</span><span><b>Oportunidades UBO</b><small>${saved?`${saved} guardada${saved===1?"":"s"}`:"Prácticas y convocatorias"}</small></span><i>›</i></button></section>`)}
function ensureMarketplaceProfileAccess(){const settings=$("#profile .settings-list"),own=marketplaceData().filter(item=>item.user===student().name).length,saved=marketplaceSaved().length;if(settings&&!$("#profile-marketplace-access"))settings.insertAdjacentHTML("beforebegin",`<section id="profile-marketplace-access" class="card-section"><button class="quick-action-card" data-go="marketplace"><span class="quick-action-icon">🛒</span><span><b>Marketplace UBO</b><small>${own} publicación${own===1?"":"es"} · ${saved} guardado${saved===1?"":"s"}</small></span><i>›</i></button></section>`)}
function ensureTrajectoryProfileAccess(){const settings=$("#profile .settings-list"),stats=trajectoryStats(),goals=studentGoals().filter(goal=>!goal.done).length;if(settings&&!$("#profile-trajectory-access"))settings.insertAdjacentHTML("beforebegin",`<section id="profile-trajectory-access" class="card-section"><button class="quick-action-card" data-go="student-trajectory"><span class="quick-action-icon">📈</span><span><b>Mi Trayectoria</b><small>${stats.percentage}% avance · ${goals} objetivo${goals===1?"":"s"}</small></span><i>›</i></button></section>`)}
renderScreen=id=>{baseRenderScreen(id);if(id==="opportunities")renderOpportunities();if(id==="marketplace")renderMarketplace();if(id==="student-trajectory")renderTrajectory();if(id==="profile"){ensureOpportunityProfileAccess();ensureMarketplaceProfileAccess();ensureTrajectoryProfileAccess()}};
const baseAiAnswer=aiAnswer;
aiAnswer=question=>{const q=question.toLowerCase();if(q.includes("práctica")||q.includes("practica")||q.includes("oportunidad")||q.includes("empleo")||q.includes("ayudant")||q.includes("investig")){const relevant=opportunities.filter(item=>!q.includes("informática")&&!q.includes("informatica")||item.career.includes("Informática")||item.career==="Todas las carreras");return `Oportunidades UBO disponibles:<br>${relevant.map(item=>`• ${item.title} · ${item.type} · cierre ${formatDate(item.deadline)}`).join("<br>")}`};return baseAiAnswer(question)};
const baseAiAnswerMarketplace=aiAnswer;
aiAnswer=question=>{const q=question.toLowerCase();if(q.includes("libro")||q.includes("apunte")||q.includes("marketplace")){const posts=marketplaceData().filter(item=>!q.includes("base de datos")||item.title.toLowerCase().includes("base de datos"));return posts.length?`Marketplace UBO tiene disponible:<br>${posts.map(item=>`• ${item.title} · ${item.type} · ${item.price}`).join("<br>")}`:"No encontré publicaciones disponibles para esa búsqueda."}return baseAiAnswerMarketplace(question)};
const baseAiAnswerTrajectory=aiAnswer;
aiAnswer=question=>{const q=question.toLowerCase();if(q.includes("cómo voy")||q.includes("como voy")||q.includes("qué debo mejorar")||q.includes("que debo mejorar")||q.includes("cuánto me falta")||q.includes("cuanto me falta")||q.includes("carrera")){const stats=trajectoryStats(),risk=courses.filter(item=>item.attendance<80).map(item=>item.name);return `Tu trayectoria muestra ${stats.percentage}% de avance curricular, promedio ${stats.average} y asistencia ${stats.attendance}%. ${risk.length?`Te conviene mejorar la asistencia en ${risk.join(", ")}. `:"Mantienes una asistencia favorable. "}Tienes ${stats.pending} ramos pendientes y ${studentGoals().filter(goal=>!goal.done).length} objetivos personales en progreso.`}return baseAiAnswerTrajectory(question)};
function login(){const username=$("#loginUsername").value.trim().toLowerCase(),password=$("#loginPassword").value,error=$("#login-error"),user=userFor(username);if(!username||!password||!user||user.password!==password){error.textContent=!username?"Ingresa tu usuario institucional para continuar.":!password?"Ingresa tu contraseña para continuar.":!user?"No encontramos ese usuario. Revisa cómo lo escribiste o usa Ayuda UBO.":"La contraseña no coincide. Revísala o solicita una recuperación demo.";error.classList.add("show");return}if($("#remember-username").checked)localStorage.setItem("uboRememberedUser",username);else localStorage.removeItem("uboRememberedUser");saveStudent({...user.student},user.username);applyDemoData(username);error.classList.remove("show");renderProfile();showScreen("home",{resetHistory:true});toast("Sesión iniciada correctamente en modo demo.")}
function submitPasswordRecovery(form){const username=$("#recovery-username").value.trim().toLowerCase(),email=$("#recovery-email").value.trim().toLowerCase(),error=$("#recovery-error"),result=$("#password-recovery-result");if(!username||!email.endsWith("@pregrado.ubo.cl")){error.textContent=!username?"Ingresa tu usuario institucional.":"Ingresa un correo institucional válido (@pregrado.ubo.cl).";error.classList.add("show");result.classList.add("hidden");return}error.classList.remove("show");result.textContent="Solicitud enviada. Recibirás instrucciones de recuperación en modo demo.";result.classList.remove("hidden");form.reset()}
function submitPublicSupport(form){const message=$("#public-support-message").value.trim();if(!message){toast("Describe tu problema para enviar la consulta.");return}const requests=json("uboPublicSupport",[]);requests.unshift({message,date:new Date().toLocaleString("es-CL")});localStorage.setItem("uboPublicSupport",JSON.stringify(requests));form.reset();toast("Consulta enviada a soporte en modo demo.")}
function logout(){localStorage.removeItem("uboSession");navigationStack=[];prepareLogin();showScreen("login");toast("Sesión cerrada correctamente.")}
function setupEvents(){document.addEventListener("click",event=>{const nav=event.target.closest("[data-go]");if(nav){if(nav.dataset.go==="institutional-mail"&&currentScreen==="mail-detail"){goBack();return}const bottom=Boolean(nav.closest(".bottom-nav")),attendanceCourse=nav.dataset.attendanceCourse;showScreen(nav.dataset.go,{resetHistory:bottom});const attendanceSelect=$("#attendance-course");if(attendanceCourse&&attendanceSelect){attendanceSelect.value=attendanceCourse;setAttendanceCalculatorValues(attendanceCourse)}return}const calendarEvent=event.target.closest("[data-calendar-event]");if(calendarEvent)return calendarEventDetail(calendarEvent.dataset.calendarEvent);const calendarCourseButton=event.target.closest("[data-calendar-course]");if(calendarCourseButton)return courseDetail(calendarCourseButton.dataset.calendarCourse);const calendarVirtualButton=event.target.closest("[data-calendar-virtual]");if(calendarVirtualButton)return classVirtual(calendarVirtualButton.dataset.calendarVirtual);const evaluation=event.target.closest("[data-evaluation]");if(evaluation)return evaluationDetail(evaluation.dataset.evaluation);const evaluationCourseButton=event.target.closest("[data-evaluation-course]");if(evaluationCourseButton)return courseDetail(evaluationCourseButton.dataset.evaluationCourse);const evaluationVirtualButton=event.target.closest("[data-evaluation-virtual]");if(evaluationVirtualButton)return classVirtual(evaluationVirtualButton.dataset.evaluationVirtual);const evaluationReminderButton=event.target.closest("[data-evaluation-reminder]");if(evaluationReminderButton)return addEvaluationReminder(evaluationReminderButton.dataset.evaluationReminder);const classCard=event.target.closest("[data-class]");if(classCard)return classDetail(classCard.dataset.class,classCard.dataset.classDay);const classVirtualButton=event.target.closest("[data-class-virtual]");if(classVirtualButton)return classVirtual(classVirtualButton.dataset.classVirtual);const course=event.target.closest("[data-course]");if(course)return courseDetail(course.dataset.course);const virtual=event.target.closest("[data-virtual]");if(virtual)return virtualDetail(virtual.dataset.virtual);const filter=event.target.closest("[data-filter]");if(filter)return renderAssignments(filter.dataset.filter);const mailF=event.target.closest("[data-mail-filter]");if(mailF){mailFilter=mailF.dataset.mailFilter;return renderMail()}const mail=event.target.closest("[data-mail]");if(mail){selectedMail=Number(mail.dataset.mail);showScreen("mail-detail");return}const toggle=event.target.closest("[data-mail-toggle]");if(toggle){const m=mailData[selectedMail];if(toggle.dataset.mailToggle==="important")m.important=!m.important;else m.unread=true;return renderMailDetail()}const day=event.target.closest("[data-day]");if(day)return renderCalendar(Number(day.dataset.day));if(event.target.closest("[data-benefit]"))return toast(event.target.closest("[data-benefit]").dataset.benefit==="Solicitar"?"Solicitud registrada en modo demo.":"Información disponible próximamente.");const toastButton=event.target.closest("[data-toast]");if(toastButton)toast(toastButton.dataset.toast);if(event.target.closest("#back-btn"))goBack();if(event.target.closest("#logout-btn"))logout();if(event.target.closest("#toggle-password")){const input=$("#loginPassword"),visible=input.type==="text";input.type=visible?"password":"text";event.target.closest("#toggle-password").setAttribute("aria-label",visible?"Mostrar contraseña":"Ocultar contraseña")}if(event.target.closest("#edit-personal")){$$("#personal-form input[name], #personal-form select[name]").forEach(i=>i.disabled=false);$("#edit-personal").classList.add("hidden");$("#personal-edit-actions").classList.remove("hidden")}if(event.target.closest("#cancel-personal"))renderPersonal();const theme=event.target.closest("[data-theme]");if(theme)document.body.classList.toggle("institutional-theme",theme.dataset.theme==="institutional");const size=event.target.closest("[data-text-size]");if(size)document.body.classList.toggle("large-text",size.dataset.textSize==="large")});document.addEventListener("submit",event=>{if(event.target.id==="login-form"){event.preventDefault();login()}if(event.target.id==="password-recovery-form"){event.preventDefault();submitPasswordRecovery(event.target)}if(event.target.id==="public-support-form"){event.preventDefault();submitPublicSupport(event.target)}if(event.target.id==="personal-form"){event.preventDefault();savePersonal(event.target)}if(event.target.id==="dae-form"){event.preventDefault();submitDae(event.target)}if(event.target.id==="reminder-form"){event.preventDefault();saveReminder(event.target)}});$("#calculate-attendance-btn").addEventListener("click",calculateAttendance);$("#attendance-course").addEventListener("change",event=>setAttendanceCalculatorValues(event.target.value));$("#simulate-btn").addEventListener("click",()=>{const a=Number($("#current-grade").value),b=Number($("#expected-grade").value),r=$("#grade-result");r.textContent=a<1||a>7||b<1||b>7?"Ingresa notas entre 1.0 y 7.0.":`Tu nota final proyectada es ${(a*.6+b*.4).toFixed(1)}.`;r.classList.remove("hidden")});$("#mail-search").addEventListener("input",renderMail);$("#reduce-motion").addEventListener("change",e=>document.body.classList.toggle("reduce-motion",e.target.checked))}
function init(){renderCourses();renderAttendance();renderAlerts();renderCertificates();renderDocuments();renderCampusEvents();renderLibrary();renderCampusMap();renderHelpCenter();renderVirtual();renderAssignments();renderSummary();renderProfile();renderDashboard();renderHomeAttention();renderHomeNotifications();renderHomeMail();renderHomeEvents();renderHomeDeliveries();renderOnboarding();prepareLogin();setupEvents();$("#public-help-btn")?.addEventListener("click",event=>{event.stopPropagation();showScreen("public-help")});$("#password-recovery-btn")?.addEventListener("click",event=>{event.stopPropagation();showScreen("password-recovery")});$("#library-search").addEventListener("input",event=>renderLibrary(libraryFilter,event.target.value));$("#campus-location-search").addEventListener("input",event=>renderCampusMap(campusLocationFilter,event.target.value));$("#help-search").addEventListener("input",event=>renderHelpCenter(event.target.value));const activeSession=session();showScreen(activeSession?"home":localStorage.getItem("uboOnboardingCompleted")==="true"?"login":"onboarding",{resetHistory:true});setTimeout(()=>$("#splash")?.classList.add("hide"),900);if("serviceWorker"in navigator&&location.protocol!=="file:")navigator.serviceWorker.register("./service-worker.js").catch(()=>{})}document.addEventListener("DOMContentLoaded",init);
document.addEventListener("click",event=>{const assignment=event.target.closest("[data-assignment]");if(assignment)return assignmentDetail(assignment.dataset.assignment);const courseButton=event.target.closest("[data-assignment-course]");if(courseButton)return courseDetail(courseButton.dataset.assignmentCourse);const virtualButton=event.target.closest("[data-assignment-virtual]");if(virtualButton)return classVirtual(virtualButton.dataset.assignmentVirtual);const reminderButton=event.target.closest("[data-assignment-reminder]");if(reminderButton)return addAssignmentReminder(reminderButton.dataset.assignmentReminder)});
document.addEventListener("click",event=>{const program=event.target.closest("[data-international]");if(program)return internationalDetail(program.dataset.international);const reminder=event.target.closest("[data-international-reminder]");if(reminder)return addInternationalReminder(reminder.dataset.internationalReminder)});
document.addEventListener("click",event=>{const filter=event.target.closest("[data-community-filter]");if(filter)return renderCommunity(filter.dataset.communityFilter);const post=event.target.closest("[data-community]");if(post)return communityDetail(post.dataset.community);const like=event.target.closest("[data-community-like]");if(like){const item=communityData().find(post=>post.id===like.dataset.communityLike);return updateCommunity(item.id,{likes:item.likes+1})}});
document.addEventListener("submit",event=>{if(event.target.id==="community-create-form"){event.preventDefault();const title=$("#community-title").value.trim(),content=$("#community-content").value.trim();if(!title||!content)return;const s=student(),saved=json("uboCommunityPosts",[]);saved.unshift({id:`community-${Date.now()}`,user:s.name,career:s.career,category:$("#community-category").value,title,content,date:"Ahora",likes:0,comments:[]});localStorage.setItem("uboCommunityPosts",JSON.stringify(saved));event.target.reset();showScreen("community",{resetHistory:false});toast("Publicación compartida en modo demo.")}if(event.target.id==="community-comment-form"){event.preventDefault();const id=event.submitter?.dataset.communityCommentId,comment=$("#community-comment").value.trim(),item=communityData().find(post=>post.id===id);if(!item||!comment)return;updateCommunity(id,{comments:[...item.comments,comment]});toast("Comentario agregado en modo demo.")}});
document.addEventListener("click",event=>{const suggestion=event.target.closest("[data-ai-question]");if(suggestion){const messages=json($("#ai-chat").dataset.messages,[]),question=suggestion.dataset.aiQuestion;messages.push({role:"user",text:question},{role:"assistant",text:aiAnswer(question)});renderAiAssistant(messages)}});
document.addEventListener("submit",event=>{if(event.target.id==="ai-form"){event.preventDefault();const question=$("#ai-input").value.trim();if(!question)return;const messages=json($("#ai-chat").dataset.messages,[]);messages.push({role:"user",text:escapeHTML(question)},{role:"assistant",text:aiAnswer(question)});$("#ai-input").value="";renderAiAssistant(messages)}});
document.addEventListener("click",event=>{const filter=event.target.closest("[data-notification-filter]");if(filter)return renderNotifications(filter.dataset.notificationFilter);const read=event.target.closest("[data-notification-read]");if(read){markNotificationRead(read.dataset.notificationRead);toast("Notificación marcada como leída.");return}const notification=event.target.closest("[data-notification]");if(notification)return notificationDetail(notification.dataset.notification);const evaluation=event.target.closest("[data-notification-evaluation]");if(evaluation)return evaluationDetail(evaluation.dataset.notificationEvaluation);const assignment=event.target.closest("[data-notification-assignment]");if(assignment)return assignmentDetail(assignment.dataset.notificationAssignment);const course=event.target.closest("[data-notification-course]");if(course)return courseDetail(course.dataset.notificationCourse)});
document.addEventListener("click",event=>{if(event.target.closest("[data-document-back]"))return goBack();const documentButton=event.target.closest("[data-document]");if(documentButton)return documentDetail(documentButton.dataset.document);const request=event.target.closest("[data-document-request]");if(request)return requestDocument(request.dataset.documentRequest);const review=event.target.closest("[data-document-review]");if(review)return checkDocumentStatus(review.dataset.documentReview);const preview=event.target.closest("[data-document-preview]");if(preview)return documentPreview(preview.dataset.documentPreview);const download=event.target.closest("[data-document-download]");if(download)return downloadDocument(download.dataset.documentDownload)});
document.addEventListener("click",event=>{const filter=event.target.closest("[data-campus-filter]");if(filter)return renderCampusEvents(filter.dataset.campusFilter);const campus=event.target.closest("[data-campus-event]");if(campus)return campusEventDetail(campus.dataset.campusEvent);const register=event.target.closest("[data-campus-register]");if(register)return registerCampusEvent(register.dataset.campusRegister);const reminder=event.target.closest("[data-campus-reminder]");if(reminder)return addCampusReminder(reminder.dataset.campusReminder);const calendar=event.target.closest("[data-campus-calendar]");if(calendar)return addCampusCalendar(calendar.dataset.campusCalendar);const notificationCampus=event.target.closest("[data-notification-campus]");if(notificationCampus)return campusEventDetail(notificationCampus.dataset.notificationCampus)});
document.addEventListener("click",event=>{const filter=event.target.closest("[data-library-filter]");if(filter)return renderLibrary(filter.dataset.libraryFilter);const book=event.target.closest("[data-library-book]");if(book)return libraryBookDetail(book.dataset.libraryBook);const reserve=event.target.closest("[data-library-reserve]");if(reserve)return reserveLibraryBook(reserve.dataset.libraryReserve);const reminder=event.target.closest("[data-library-reminder]");if(reminder)return addLibraryReminder(reminder.dataset.libraryReminder);const notificationBook=event.target.closest("[data-notification-library]");if(notificationBook)return libraryBookDetail(notificationBook.dataset.notificationLibrary)});
document.addEventListener("click",event=>{const filter=event.target.closest("[data-campus-location-filter]");if(filter)return renderCampusMap(filter.dataset.campusLocationFilter);const location=event.target.closest("[data-campus-location]");if(location)return campusLocationDetail(location.dataset.campusLocation);const nearby=event.target.closest("[data-campus-nearby]");if(nearby)return showCampusNearby(nearby.dataset.campusNearby);const reminder=event.target.closest("[data-campus-location-reminder]");if(reminder)return addCampusLocationReminder(reminder.dataset.campusLocationReminder)});
document.addEventListener("click",event=>{const article=event.target.closest("[data-help]");if(article)return helpDetail(article.dataset.help);const go=event.target.closest("[data-help-go]");if(go)return showScreen(go.dataset.helpGo);const tech=event.target.closest("[data-help-tech]");if(tech)return $("#tech-help-form").classList.toggle("hidden")});
document.addEventListener("submit",event=>{if(event.target.id==="tech-help-form"){event.preventDefault();submitTechnicalHelp(event.target)}});
document.addEventListener("click",event=>{if(event.target.closest("[data-onboarding-next]")){onboardingIndex=Math.min(onboardingIndex+1,onboardingSlides.length-1);return renderOnboarding()}if(event.target.closest("[data-onboarding-prev]")){onboardingIndex=Math.max(onboardingIndex-1,0);return renderOnboarding()}if(event.target.closest("[data-onboarding-skip]")||event.target.closest("[data-onboarding-complete]"))return completeOnboarding()});
document.addEventListener("DOMContentLoaded",()=>{const node=$("#home-date");if(node)node.textContent=new Intl.DateTimeFormat("es-CL",{weekday:"long",day:"numeric",month:"long"}).format(new Date())});
document.addEventListener("click",event=>{const launcher=event.target.closest("#ai-float-btn");if(launcher){const widget=$("#ai-chat-widget");widget.classList.toggle("hidden");if(!widget.classList.contains("hidden")&&!$("#ai-widget-messages").innerHTML)renderAiWidget();return}if(event.target.closest("#ai-widget-close")||event.target.closest("#ai-widget-minimize")){ $("#ai-chat-widget").classList.add("hidden");return}const suggestion=event.target.closest("[data-ai-widget-question]");if(suggestion)askAiWidget(suggestion.dataset.aiWidgetQuestion)});
